\section{Introduction}

Time--frequency analysis studies a signal $f:\RR\to\CC$ through its correlations with translated
and modulated copies of a fixed window. The choice of window is essentially canonical: the Gaussian
\[
  g_s(t)=e^{-\pi t^2/s^2},\qquad s>0,
\]
uniquely saturates the uncertainty inequality and is, up to width, a fixed point of the Fourier
transform.

Two operators act on windows,
\[
  (T_af)(t)=f(t-a),\qquad (M_bf)(t)=\chi(bt)f(t),
\]
where throughout $\chi(x)=e^{2\pi ix}$, so that $\chi(x+y)=\chi(x)\chi(y)$ and $\chi(x)=1$ if and
only if $x\in\ZZ$. They fail to commute by the Weyl phase, $M_bT_a=\chi(ba)T_aM_b$, and generate the
\emph{Heisenberg group}
\[
  \Heis=\{(a,b,z):a,b\in\RR,\ |z|=1\},\qquad
  (a,b,z)(a',b',z')=(a+a',\,b+b',\,zz'\chi(ba')),
\]
acting on windows by the Schr\"odinger representation
$\big(\rho(a,b,z)f\big)(t)=z\,\chi(b(t-a))f(t-a)$. The \emph{Gabor atom} at the phase-space point
$(a,b)$ is
\[
  g_{s,a,b}(t)=\chi\big(b(t-a)\big)\,g_s(t-a).
\]

The group $\Heis$ implements only the translations of phase space $\RR^2_{(a,b)}$. Phase space is
however symplectic, and its full linear symmetry group is $\SL$. The purpose of this paper is to
build the corresponding action on windows constructively, one generator at a time, and to locate
precisely where and why an honest lift fails. The organising principle is that \emph{windows form a
hyperbolic plane}: once the Gaussians are completed to the chirped Gaussians, the parameter space is
$\HH$ and each window operation is a familiar isometry --- shear, geodesic flow, rotation. Two of the
three lift honestly; the third does not, and its failure is measurable on a single explicit pair of
atoms.

We use the Fourier normalisation $\widehat f(\xi)=\int_\RR f(t)e^{-2\pi it\xi}\,dt$, for which
$\Ft g_s=s\,g_{1/s}$ and $\Ft^4=\mathrm{id}$ on Schwartz functions. The group $\SL$ acts on
$\HH=\{z:\Ima z>0\}$ by $\left(\begin{smallmatrix}p&q\\r&w\end{smallmatrix}\right)\cdot z=(pz+q)/(rz+w)$,
an action factoring through $\mathrm{PSL}_2(\RR)$; the kernel $\{\pm I\}$ is the entire source of
what follows.

\section{The chirp generator and the extended cocycle}

\begin{definition}[Chirp operator]
For $c\in\RR$ set $(C_cf)(t)=\chi(ct^2)f(t)=e^{2\pi ict^2}f(t)$.
\end{definition}

Immediately $C_0=\mathrm{id}$, $C_cC_{c'}=C_{c+c'}$ (so $C_c^{-1}=C_{-c}$), $C_c$ is linear, and
$C_c$ commutes with every modulation, both being multiplication operators.

\begin{theorem}[Chirp--translation relation]\label{thm:ct}
For all $a,c\in\RR$ and all $f$,
\[
  C_c\,T_a\,f=\chi(-ca^2)\,M_{2ac}\,T_a\,C_c\,f .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Evaluate at $t$. The left side is $\chi(ct^2)f(t-a)$; the right side is
$\chi(-ca^2)\chi(2act)\chi(c(t-a)^2)f(t-a)$. Combining the phases on the right,
$-ca^2+2act+c(t-a)^2=ct^2$.
\end{proof}

Read on phase space, Theorem~\ref{thm:ct} is the shear $(a,b)\mapsto(a,b+2ca)$.

\begin{definition}[Chirp shear]
For $c\in\RR$ define $\sigma_c:\Heis\to\Heis$ by $\sigma_c(a,b,z)=\big(a,\,b+2ca,\,z\chi(ca^2)\big)$.
\end{definition}

\begin{theorem}[The Weyl cocycle extends]\label{thm:aut}
$\sigma_c$ is a group automorphism of $\Heis$, with $\sigma_0=\mathrm{id}$ and
$\sigma_c\circ\sigma_{c'}=\sigma_{c+c'}$; thus $c\mapsto\sigma_c$ is a homomorphism
$\RR\to\Aut(\Heis)$.
\end{theorem}

\begin{proof}[Proof sketch]
Only the central coordinate requires work. For $g=(a,b,z)$ and $h=(a',b',z')$ the central
coordinate of $\sigma_c(gh)$ is $zz'\chi(ba')\chi\big(c(a+a')^2\big)$, and that of
$\sigma_c(g)\sigma_c(h)$ is $z\chi(ca^2)z'\chi(ca'^2)\chi\big((b+2ca)a'\big)$; the identity
$c(a+a')^2=ca^2+ca'^2+2caa'$ makes them agree. The correction phase $\chi(ca^2)$ is therefore
forced: it is exactly the coboundary keeping the Weyl cocycle in its class under the shear.
\end{proof}

\begin{theorem}[Normality and intertwining]\label{thm:semidirect}
Let $\Heis\rtimes_\sigma\RR$ be the semidirect product determined by $c\mapsto\sigma_c$. Then
$\Heis$ is normal in it, being the kernel of the projection to $\RR$, and the chirp operator
implements the automorphism on windows:
\[
  \rho\big(\sigma_cg\big)\,C_c\,f=C_c\,\rho(g)\,f\qquad(g\in\Heis).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Evaluated at $t$ and after cancelling $zf(t-a)$, the identity reduces to the polynomial identity
$ca^2+(b+2ca)(t-a)+c(t-a)^2=ct^2+b(t-a)$. Normality is formal.
\end{proof}

Consequently the pair (Schr\"odinger representation, chirp multiplication) assembles into a single
representation of $\Heis\rtimes_\sigma\RR$ by invertible operators on window space.

\begin{lemma}[Rigidity of quadratic characters]\label{lem:rigid}
If $b,c\in\RR$ and $\chi(bt+ct^2)=1$ for all $t\in\RR$, then $b=c=0$.
\end{lemma}

\begin{proof}[Proof sketch]
Put $M=1+|b|+|c|$ and $T=1/(2M)\le\frac12$. For $|t|\le T$ we have $|t|^2\le|t|\le T$, hence
$|bt+ct^2|\le(|b|+|c|)T\le MT=\frac12<1$. But $\chi(x)=1$ forces $x\in\ZZ$, and the only integer of
absolute value $<1$ is $0$; so $bt+ct^2=0$ on $[-T,T]$. Taking $t=T$ and $t=T/2$ yields $c=0$ and
then $b=0$.
\end{proof}

\begin{theorem}[Faithfulness]\label{thm:faithful}
The representation of $\Heis\rtimes_\sigma\RR$ on window space is faithful: if
$\rho(g)C_c=\mathrm{id}$ then $g=1$ and $c=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply the operator to $g_1$ and write $g=(a,b,z)$. Taking absolute values kills all phases and
leaves $g_1(t-a)=g_1(t)$ for all $t$; at $t=0$ this gives $e^{-\pi a^2}=1$, so $a=0$. The identity
becomes $z\chi(bt+ct^2)g_1(t)=g_1(t)$ with $g_1(t)\ne0$, hence $z\chi(bt+ct^2)=1$; at $t=0$, $z=1$,
and Lemma~\ref{lem:rigid} gives $b=c=0$.
\end{proof}

\begin{theorem}[The chirp automorphism is outer]\label{thm:outer}
For $c\ne0$ there is no $h\in\Heis$ with $\sigma_c(g)=hgh^{-1}$ for all $g\in\Heis$. Hence
$\Heis\rtimes_\sigma\RR$ is not a direct product.
\end{theorem}

\begin{proof}[Proof sketch]
Conjugation in $\Heis$ leaves the $b$-coordinate unchanged, whereas $\sigma_c(1,0,1)=(1,2c,\chi(c))$
has $b$-coordinate $2c\ne0$.
\end{proof}

\section{Chirped Gaussians and the Siegel parameter}

\begin{definition}[Chirped Gaussian]
For $\alpha>0$, $\beta\in\RR$ put $G_{\alpha,\beta}(t)=e^{-\pi(\alpha+i\beta)t^2}$ and
$\tau=\alpha+i\beta$, so $\Rea\tau>0$.
\end{definition}

The function never vanishes, $|G_{\alpha,\beta}(t)|=e^{-\pi\alpha t^2}$ (the chirp is a pure phase,
invisible to the envelope), and $\tau\ne0$. For $s\ne0$ one has $G_{1/s^2,0}=g_s$, so the family
extends the Gaussian windows.

\begin{proposition}[Chirp and dilation act on the parameters]\label{prop:cd}
With $(D_uf)(t)=f(e^{-u}t)$,
\[
  C_c\,G_{\alpha,\beta}=G_{\alpha,\,\beta-2c},\qquad
  D_u\,G_{\alpha,\beta}=G_{e^{-2u}\alpha,\,e^{-2u}\beta},
\]
and on the unchirped subfamily $D_ug_s=g_{e^us}$. Moreover $D_0=\mathrm{id}$ and
$D_uD_{u'}=D_{u+u'}$.
\end{proposition}

\begin{proof}[Proof sketch]
$\chi(ct^2)e^{-\pi(\alpha+i\beta)t^2}=e^{-\pi(\alpha+i(\beta-2c))t^2}$, and $(e^{-u}t)^2=e^{-2u}t^2$.
\end{proof}

\begin{theorem}[Width inversion]\label{thm:fourier}
Let $\tau=\alpha+i\beta$ with $\alpha>0$. Then $\Ft(G_{\alpha,\beta})=\tau^{-1/2}G_{1/\tau}$, i.e.
\[
  \Ft\big(G_{\alpha,\beta}\big)(\xi)
    =\frac{1}{(\alpha+i\beta)^{1/2}}\;
      G_{\frac{\alpha}{\alpha^2+\beta^2},\;\frac{-\beta}{\alpha^2+\beta^2}}(\xi),
\]
with the principal branch of the square root, legitimate because $\Rea\tau>0$.
\end{theorem}

\begin{proof}[Proof sketch]
This is the Gaussian integral $\int e^{-\pi\tau t^2}e^{-2\pi it\xi}\,dt=\tau^{-1/2}e^{-\pi\xi^2/\tau}$,
valid for $\Rea\tau>0$ by analytic continuation from real $\tau>0$. Writing $1/\tau$ in real
coordinates via $(\alpha+i\beta)(\alpha-i\beta)=\alpha^2+\beta^2$ gives the stated form.
\end{proof}

Setting $\beta=0$, $\alpha=1/s^2$ recovers $\Ft g_s=s\,g_{1/s}$. Note that the hypothesis $\alpha>0$
is simultaneously the integrability condition for the Gaussian integral and the condition placing
the parameter below in the upper half-plane.

\begin{definition}[Siegel parameter]
For $\alpha>0$ put
\[
  z(\alpha,\beta)=\frac{i}{\alpha+i\beta}
   =\frac{\beta}{\alpha^2+\beta^2}+i\,\frac{\alpha}{\alpha^2+\beta^2}.
\]
\end{definition}

Then $\Ima z=\alpha/(\alpha^2+\beta^2)>0$, so $z\in\HH$, and $z$ is injective on $\{\alpha>0\}$ since
$z(\alpha,\beta)=z(\alpha',\beta')$ forces $\alpha+i\beta=\alpha'+i\beta'$. The chirped Gaussian
family is thus faithfully coordinatised by the upper half-plane. Introduce
\[
  N_c=\begin{pmatrix}1&0\\-2c&1\end{pmatrix},\qquad
  A_u=\begin{pmatrix}e^u&0\\0&e^{-u}\end{pmatrix},\qquad
  S=\begin{pmatrix}0&-1\\1&0\end{pmatrix}
   =\begin{pmatrix}\cos\frac\pi2&-\sin\frac\pi2\\[2pt]\sin\frac\pi2&\cos\frac\pi2\end{pmatrix},
\]
so that $N_cN_{c'}=N_{c+c'}$, $A_uA_{u'}=A_{u+u'}$, $S^2=-I$ and $S^4=I$.

\begin{theorem}[Equivariance]\label{thm:equiv}
For $\alpha>0$:
\begin{enumerate}
\item (chirp $=$ shear) $z(\alpha,\beta-2c)=N_c\cdot z(\alpha,\beta)=\dfrac{z}{-2cz+1}$;
\item (dilation $=$ diagonal) $z\big(e^{-2u}\alpha,e^{-2u}\beta\big)=A_u\cdot z(\alpha,\beta)=e^{2u}z$;
\item (Fourier $=$ rotation by $\pi/2$)
      $z\!\left(\frac{\alpha}{\alpha^2+\beta^2},\frac{-\beta}{\alpha^2+\beta^2}\right)
       =S\cdot z(\alpha,\beta)=-1/z$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
Write $\tau=\alpha+i\beta$, $z=i/\tau$. (1) Chirping replaces $\tau$ by $\tau-2ic$, and
$-2cz+1=(\tau-2ic)/\tau$, so $z/(-2cz+1)=i/(\tau-2ic)$. (2) Dilating replaces $\tau$ by
$e^{-2u}\tau$, hence $z$ by $e^{2u}z$. (3) By Theorem~\ref{thm:fourier} the Fourier transform
replaces $\tau$ by $1/\tau$, hence $z$ by $i\tau=-1/z$.
\end{proof}

