\section{The width geodesic and the scale space}

\begin{theorem}[Windows on the imaginary axis]\label{thm:geodesic}
For $s>0$ the window $g_s=G_{1/s^2,0}$ has Siegel parameter $z=is^2$, so $\Rea z=0$: the classical
family of window widths is exactly the imaginary geodesic of $\HH$. Moreover $g_{e^us}$ has Siegel
parameter $A_u\cdot(is^2)=e^{2u}is^2$, so changing the width is precisely the diagonal one-parameter
subgroup acting along that geodesic.
\end{theorem}

Let $S$ be a finite multiset of real ordinates and
\[
  \Sigma(S,s)=\sum_{t\in S}e^{-\pi t^2/s^2}
\]
the aggregate response of a width-$s$ Gaussian window to $S$; it is nondecreasing in $s$, strictly
increasing as soon as some $t\in S$ is nonzero.

\begin{theorem}[Monotonicity is the diagonal flow]\label{thm:mono}
For every finite multiset $S$ and every $s>0$ the map $u\mapsto\Sigma(S,e^us)$ is monotone, and
strictly monotone whenever some $t\in S$ is nonzero.
\end{theorem}

\begin{proof}[Proof sketch]
$u\mapsto e^us$ is strictly increasing with values in $(0,\infty)$; compose with monotonicity of
$\Sigma(S,\cdot)$. The content is the reading rather than the inequality: $u$ is the time of the
diagonal flow, so a one-parameter subgroup moves the Siegel point monotonically along a geodesic.
\end{proof}

\begin{theorem}[Transversality of the chirp]\label{thm:transverse}
For $s>0$ and $c\ne0$ the chirped window $C_cg_s=G_{1/s^2,-2c}$ has
\[
  \Rea z=\frac{-2c}{(1/s^2)^2+4c^2}\ne0 .
\]
Hence a nonzero chirp always moves the window off the imaginary geodesic, and consequently
$C_cg_s\ne g_{s'}$ for every $s'$.
\end{theorem}

\begin{proof}[Proof sketch]
The displayed real part is nonzero because $c\ne0$ and the denominator is positive; plain windows
have $\Rea z=0$ and $z$ is injective. Directly: choose $t=(4|c|)^{-1/2}$, so $|c|t^2=1/4$; then
$C_cg_s(t)=\chi(\pm1/4)g_s(t)$ has imaginary part $\pm g_s(t)\ne0$, while $g_{s'}(t)$ is real.
\end{proof}

Thus $\{g_s\}$ is \emph{not} stable under the metaplectic action, and the two-parameter chirped
family is the smallest completion that is.

\section{The Borel subgroup: transitivity and an honest lift}

Let $B$ be the lower Borel subgroup of $\SL$ generated by the shears $N_c$ and the diagonal torus
$A_u$.

\begin{theorem}[Borel commutation relation, twice]\label{thm:borelcomm}
For all $u,c$,
\[
  D_u\,C_c\,D_u^{-1}=C_{e^{-2u}c}
  \qquad\text{and}\qquad
  A_u\,N_c\,A_u^{-1}=N_{e^{-2u}c}.
\]
The operator relation and the matrix relation agree exactly: on $B$ the phase-space action lifts to
windows with no discrepancy.
\end{theorem}

\begin{proof}[Proof sketch]
$\big(D_uC_cD_{-u}f\big)(t)=\chi\big(c(e^{-u}t)^2\big)f(e^ue^{-u}t)=\chi(e^{-2u}ct^2)f(t)$; and the
off-diagonal entry of $\mathrm{diag}(e^u,e^{-u})N_c\,\mathrm{diag}(e^{-u},e^u)$ is $-2ce^{-2u}$.
\end{proof}

\begin{theorem}[Transitivity]\label{thm:borelorbit}
For every $\alpha>0$ and $\beta\in\RR$,
\[
  G_{\alpha,\beta}=C_{-\beta/2}\;D_{-\frac12\log\alpha}\;G_{1,0},
\]
equivalently $z(\alpha,\beta)=N_{-\beta/2}A_{-\frac12\log\alpha}\cdot i$: the Borel orbit of the
standard point $i$ is all of $\HH$.
\end{theorem}

\begin{proof}[Proof sketch]
For $u=-\frac12\log\alpha$ one has $e^{-2u}=\alpha$, so $D_uG_{1,0}=G_{\alpha,0}$; then
$C_{-\beta/2}G_{\alpha,0}=G_{\alpha,\beta}$ by Proposition~\ref{prop:cd}. The parameters
$u=-\frac12\log\alpha$, $c=-\beta/2$ are the exponential coordinates of the Borel Lie algebra.
\end{proof}

\begin{remark}
Transitivity is of the \emph{lower} Borel: the chirp is the lower unipotent $N_c$, which fixes $0$,
not $\infty$; the upper unipotent (a horizontal translation of the Siegel parameter) is not
implemented by multiplication by a chirp on this family. Crucially for the next section, $B$ is
contractible, which is exactly why the lift can be honest here.
\end{remark}

\begin{theorem}[Dilations also normalise $\Heis$]\label{thm:dilaut}
The map $\delta_u(a,b,z)=(e^ua,\,e^{-u}b,\,z)$ is an automorphism of $\Heis$ --- with no phase
correction --- and $\rho(\delta_ug)D_u=D_u\rho(g)$. Hence $\Heis$ is normal in
$\Heis\rtimes_\delta\RR$ as well.
\end{theorem}

\begin{proof}[Proof sketch]
The Weyl cocycle is literally invariant, $(e^{-u}b)(e^ua')=ba'$; the intertwining identity is the
change of variable $t\mapsto e^{-u}t$.
\end{proof}

The contrast with Theorem~\ref{thm:aut} is instructive: the diagonal subgroup preserves the
symplectic form pointwise on the cocycle, so no phase appears, whereas the shear preserves it only
up to the coboundary $\chi(ca^2)$.

\section{The metaplectic anomaly}

\begin{theorem}[$\Ft^2$ is parity]\label{thm:parity}
For $s>0$ and $a,b\in\RR$, $\ \Ft^2\big(g_{s,a,b}\big)=g_{s,-a,-b}$, with no extra constant.
Consequently $\Ft^4\big(g_{s,a,b}\big)=g_{s,a,b}$, matching $S^4=I$.
\end{theorem}

\begin{proof}[Proof sketch]
The rules $\Ft T_a=M_{-a}\Ft$, $\Ft M_b=T_b\Ft$ and $\Ft g_s=s\,g_{1/s}$ give
$\Ft(g_{s,a,b})=s\,M_{-a}T_b\,g_{1/s}$, the width-$(1/s)$ atom at the rotated point $(b,-a)$ scaled
by $s$. Applying them again returns the width to $s$, producing the scalar $1/s$; the constants
cancel exactly and the phase-space point rotates to $(-a,-b)$.
\end{proof}

\begin{lemma}[$-I$ acts trivially downstairs]\label{lem:minusone}
For every $z\in\HH$, $(-I)\cdot z=\frac{-z+0}{0-1}=z$; in particular $S^2\cdot z=z$.
\end{lemma}

\begin{theorem}[Separation of opposite atoms]\label{thm:sep}
If $s>0$ and $(a,b)\ne(0,0)$ then $g_{s,-a,-b}\ne g_{s,a,b}$.
\end{theorem}

\begin{proof}[Proof sketch]
Two cases, with two different invariants. If $a\ne0$, evaluate at $t=a$ and take moduli: the left
side has modulus $g_s(2a)$ and the right side $g_s(0)=1$, but $g_s(2a)<1$. If $a=0$ and $b\ne0$, the
envelopes agree and never vanish, so equality would force $\chi(-bt)=\chi(bt)$ for all $t$; taking
$t=1/(4b)$ gives $\chi(-1/4)=\chi(1/4)$, hence $\chi(1/2)=1$, which is false.
\end{proof}

\begin{theorem}[The metaplectic anomaly]\label{thm:anomaly}
Let $s>0$ and $(a,b)\ne(0,0)$. Then simultaneously
\[
  \forall z\in\HH:\ (S^2)\cdot z=z
  \qquad\text{and}\qquad
  \Ft^2\big(g_{s,a,b}\big)\ne g_{s,a,b}.
\]
Hence no assignment $M\mapsto\rho(M)$ from $\SL$ to operators on window space can be simultaneously
a homomorphism and an implementation of the phase-space action: the honest symmetry group of the
window is the metaplectic double cover.
\end{theorem}

\begin{proof}[Proof sketch]
Combine Lemma~\ref{lem:minusone}, Theorem~\ref{thm:parity} and Theorem~\ref{thm:sep}. An honest lift
would force $\rho(S)^2=\rho(-I)$ to act as the identity, since $-I$ fixes every window parameter;
but it acts by parity.
\end{proof}

\begin{theorem}[Projective anomaly]\label{thm:proj}
Let $s>0$ and $(a,b)\ne(0,0)$. For every $\kappa\in\CC$,
\[
  \kappa\,\Ft^2\big(g_{s,a,b}\big)\ne g_{s,a,b};
\]
equivalently, the atoms at $(a,b)$ and $(-a,-b)$ are not even proportional. Thus no rescaling of the
lift removes the obstruction, which is a genuine order-two class.
\end{theorem}

\begin{proof}[Proof sketch]
If $a\ne0$, taking moduli gives $|\kappa|g_s(t+a)=g_s(t-a)$ for all $t$; at $t=-a$ this yields
$|\kappa|=g_s(2a)$ and at $t=a$ it yields $|\kappa|g_s(2a)=1$, whence $g_s(2a)^2=1$, contradicting
$0<g_s(2a)<1$. If $a=0$ and $b\ne0$, evaluating at $t=0$ forces $\kappa=1$, and
Theorem~\ref{thm:sep} applies.
\end{proof}

\begin{remark}[Boundaries of the phenomenon]
Three remarks sharpen the statement. (i) The anomaly is invisible at the origin: for $a=b=0$ the
atom is the Gaussian itself, which is even, so parity fixes it; the hypothesis $(a,b)\ne(0,0)$ is a
genuine boundary. (ii) It is of order exactly two: $\Ft^2\ne\mathrm{id}$ but $\Ft^4=\mathrm{id}$,
mirroring $S^2=-I\ne I$, $S^4=I$, and the kernel of $\SL\to\mathrm{PSL}_2(\RR)$ is
$\{\pm I\}\cong\ZZ/2$. (iii) It is concentrated at the Weyl element: by
Theorem~\ref{thm:borelcomm} the (contractible) Borel subgroup lifts honestly, while $\SL$ is not
simply connected, its maximal compact being a circle. Concretely the scalar $\tau^{-1/2}$ of
Theorem~\ref{thm:fourier} is where the sign lives: following the branch of $\tau^{1/2}$ continuously
around a loop composed with $\tau\mapsto1/\tau$ returns the other square root, and the
double-valuedness of the metaplectic representation is exactly that of the square root.
\end{remark}

\section{The discrete theory: a lattice anomaly}

A digital, multiset-supported Gabor transform places atoms on a lattice. Let
\[
  \Lambda=\{(a,b,z)\in\Heis:\ a\in\ZZ,\ b\in\ZZ\}
\]
be the integer Heisenberg lattice.

\begin{theorem}[Discrete metaplectic anomaly]\label{thm:lattice}
$\sigma_c(\Lambda)\subseteq\Lambda$ if and only if $2c\in\ZZ$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) Apply $\sigma_c$ to $(1,0,1)$: the image has $b$-coordinate $2c$, necessarily an
integer. ($\Leftarrow$) If $2c=n\in\ZZ$ and $a=m$, $b=k$ are integers then the image has
$b$-coordinate $k+nm\in\ZZ$ and unchanged $a$-coordinate $m$.
\end{proof}

Continuously, chirps form a full one-parameter group $\RR$; discretely only the lattice
$\frac12\ZZ$ of chirp rates survives. The symmetry group of the discrete transform is therefore
arithmetic rather than continuous, and the metaplectic sign must be tracked over an arithmetic
group, where --- unlike over the contractible Borel --- it cannot be normalised away by a continuous
choice of branch.

\section{Algorithms}

\textbf{Borel factorisation.} Given $(\alpha,\beta)$ with $\alpha>0$, return
$u=-\frac12\log\alpha$, $c=-\beta/2$; then $G_{\alpha,\beta}=C_cD_uG_{1,0}$ by
Theorem~\ref{thm:borelorbit}. Cost $O(1)$; the map $(\alpha,\beta)\mapsto(u,c)$ is a global
diffeomorphism onto $\RR^2$, the analytic form of simple transitivity of $B$ on $\HH$.

\textbf{Metaplectic word evaluation.} Given a word $W$ in the letters $C_c,D_u,\Ft$, compute both
the matrix $\pi(W)\in\SL$ obtained by substituting $N_c,A_u,S$, and the image of a chirped Gaussian
tracked as a pair (complex width, accumulated scalar) using $\tau\mapsto\tau-2ic$,
$\tau\mapsto e^{-2u}\tau$, and $\tau\mapsto1/\tau$ with scalar $\times\tau^{-1/2}$. Cost $O(|W|)$.
By Theorem~\ref{thm:equiv} the Siegel parameters satisfy $z(\text{out})=\pi(W)\cdot z(\text{in})$,
while the accumulated scalar is the datum the matrix does not see.

\textbf{Anomaly detector.} Given a word $W$ with $\pi(W)=\pm I$, a width $s$ and a point $(a,b)$,
report $\sup_t\big||Wg_{s,a,b}(t)|-|g_{s,a,b}(t)|\big|$ and the failure of
$t\mapsto Wg_{s,a,b}(t)/g_{s,a,b}(t)$ to be constant. For $W=\Ft^2$ and $(a,b)\ne(0,0)$ both are
nonzero, certifying Theorems~\ref{thm:anomaly} and \ref{thm:proj}; for $W=\Ft^4$ both vanish.

\section{Applications and discussion}

Radar, sonar, gravitational-wave templates, magnetic-resonance gradient encoding and chirp
spread-spectrum radio all produce locally chirped signals, analysed by rotating phase space through
an angle $\theta$ --- the fractional Fourier transform --- so that the chirp aligns with the
frequency axis. Theorem~\ref{thm:equiv} identifies the correct window at angle $\theta$ as the
chirped Gaussian whose Siegel parameter is the image of $i$ under the corresponding rotation, and
Theorem~\ref{thm:borelorbit} gives its parameters in closed form. Any implementation must choose a
branch of a square root; Theorem~\ref{thm:proj} says the resulting sign ambiguity is intrinsic, so
consistency of composition can be achieved only up to $\pm1$. Theorem~\ref{thm:mono} reinterprets
scale-space monotonicity as geodesic flow, and the hyperbolic metric supplies a canonical,
reparametrisation-invariant distance between windows, including chirped ones that the classical
picture cannot compare. Theorem~\ref{thm:lattice} tells a designer of a discrete scheme exactly
which chirps are lattice-compatible: the half-integers, and no others.

The results split along the topology of $\SL$. Everything contractible lifts: the Heisenberg group
is normalised by both the chirp and the dilation subgroups, the semidirect products carry faithful
honest representations, and the Borel commutation relation holds identically on both sides. The one
nontrivial phase, $\chi(ca^2)$, is a coboundary forced by $c(a+a')^2=ca^2+2caa'+ca'^2$. Nothing
about the rotation lifts: the obstruction is detected at $S^2=-I$ by two completely elementary
invariants --- the modulus when $a\ne0$, since a Gaussian bell cannot be a constant multiple of its
own reflection, and the quarter period of $\chi$ when $a=0$, $b\ne0$, since the envelopes then
coincide and the modulus is blind.

\textbf{Limitations.} We work in one dimension; in $n$ dimensions $\HH$ is replaced by the Siegel
upper half-space and the sign by the Maslov index. The equivariance statements are specific to the
chirped Gaussian family, which is the orbit of the Gaussian, though the anomaly statements concern
Gabor atoms and are insensitive to that. Transitivity is for the lower Borel only.

\section{Future directions}

\begin{conjecture}[Explicit metaplectic 2-cocycle]
There is $m:\SL\times\SL\to\{\pm1\}$ such that the window operator $\rho(M)$ implementing $M$ on the
chirped Gaussian family, normalised by the positive square root of the width, satisfies
$\rho(M)\rho(N)=m(M,N)\rho(MN)$, with $m$ a nontrivial $2$-cocycle whose restriction to the Borel
subgroup is a coboundary.
\end{conjecture}

The results above already separate the two regimes: the Borel lifts honestly while the failure is
concentrated at the rotation, so the cocycle is supported on the Weyl element and is exactly the
Maslov sign. The only new ingredient is bookkeeping of the branch of $\tau^{1/2}$. The first step is
discharged: Theorem~\ref{thm:proj} rules out $m\equiv1$.

\begin{conjecture}[Discrete anomaly]
For a multiset-supported Gabor transform on $\Lambda=\ZZ\times\ZZ$, the subgroup of $\SL$ acting on
lattice-supported windows is exactly $\mathrm{SL}_2(\ZZ)$, and its lift is the restriction of the
metaplectic cocycle --- a nontrivial class detected by the theta multiplier. The half-integrality
$2c\in\ZZ$ of Theorem~\ref{thm:lattice} is the first symptom: the lattice shears are generated by
$c=1/2$, whose square is the standard unipotent generator of $\mathrm{SL}_2(\ZZ)$.
\end{conjecture}

A third problem is to interpolate between the identity and $\Ft$ along the rotation subgroup,
tracking the branch of $\tau^{-1/2}$ continuously; the expected outcome is an explicit winding
number computing the Maslov index, with the anomaly above as its value at angle $\pi$. Longer range,
one should replace $\HH$ by the Siegel upper half-space and $\SL$ by $\mathrm{Sp}_{2n}(\RR)$, the
chirp becoming multiplication by $e^{2\pi i\langle Qt,t\rangle}$ and the correction phase becoming
$\chi(\langle Qa,a\rangle)$; and one should sum discrete windows over $\Lambda$ to produce theta
series in the Siegel parameter, identifying the discrete metaplectic sign with the classical theta
multiplier and closing the bridge from time--frequency analysis to modular forms.

\section{Conclusion}

Adding one operator --- the chirp $e^{2\pi ict^2}$ --- to the two classical Gabor generators
completes the Heisenberg group to a semidirect product in which it is normal, completes the Gaussian
window to a family parametrised by the hyperbolic plane, and turns three unrelated facts about
windows into a single statement of $\SL$-equivariance. Along the contractible directions the
correspondence is exact. At the rotation it fails by exactly a sign: $S^2=-I$ moves no window
parameter, yet $\Ft^2$ reflects every Gabor atom through the origin of phase space, and no rescaling
repairs it. The symmetry group of the Gabor window is not $\SL$ but its double cover; discretely,
only the half-integer shears survive, and the anomaly becomes arithmetic.

