function BOREL-FACTORISE(alpha, beta):
    require alpha > 0                          # integrability of the window
    u <- -log(alpha) / 2                       # diagonal (dilation) coordinate
    c <- -beta / 2                             # shear (chirp) coordinate
    return (u, c)

function BOREL-SYNTHESISE(u, c):
    alpha <- exp(-2u)
    beta  <- -2c
    return (alpha, beta)

function VERIFY(alpha, beta, samples):
    (u, c) <- BOREL-FACTORISE(alpha, beta)
    worst <- 0
    for each sample point t:
        built  <- exp(2*pi*i*c*t^2) * exp(-pi * (exp(-u) t)^2)
        target <- exp(-pi (alpha + i beta) t^2)
        worst  <- max(worst, |built - target|)
    return worst                               # zero to machine precision

function EVALUATE-WORD(W, tau):
    require Re(tau) > 0
    M <- identity matrix;  kappa <- 1
    for each letter (kind, p) in W, left to right:
        if kind = 'chirp':
            tau <- tau - 2 i p;                 L <- [[1,0],[-2p,1]]
        else if kind = 'dilate':
            tau <- exp(-2p) * tau;              L <- diag(e^p, e^-p)
        else if kind = 'fourier':
            kappa <- kappa * tau^(-1/2)
            tau   <- 1 / tau;                   L <- [[0,-1],[1,0]]
        M <- L * M
    return (M, tau, kappa)

function EQUIVARIANCE-ERROR(W, tau):
    (M, tau_out, kappa) <- EVALUATE-WORD(W, tau)
    return | i/tau_out  -  MOEBIUS(M, i/tau) |   # zero: the equivariance theorem

