"""Metaplectic word evaluation on the chirped Gaussian family.

A *word* is a finite sequence of the three basic window operations

    ("chirp", c)     (C_c f)(t) = exp(2 pi i c t^2) f(t)
    ("dilate", u)    (D_u f)(t) = f(exp(-u) t)
    ("fourier", _)   (F f)(xi)  = integral f(t) exp(-2 pi i t xi) dt

applied left to right to a chirped Gaussian G_{alpha,beta}(t) = exp(-pi tau t^2),
tau = alpha + i beta.  Two things are tracked simultaneously:

  * the SL2(R) matrix obtained by substituting the shear N_c = [[1,0],[-2c,1]],
    the diagonal A_u = diag(e^u, e^-u) and the rotation S = [[0,-1],[1,0]];
  * the state of the window, as the pair (tau, scalar), evolving by
        chirp    : tau -> tau - 2 i c,          scalar unchanged
        dilate   : tau -> e^{-2u} tau,          scalar unchanged
        fourier  : tau -> 1 / tau,              scalar -> scalar * tau^{-1/2}.

The theorem being illustrated is that the Siegel parameter z = i / tau transforms
by the Moebius action of the accumulated matrix,

        z(output) = M . z(input),        M = product of the substituted matrices,

so the *shape* of the window is completely predicted by phase-space geometry --
while the accumulated scalar is the extra datum that the matrix does not see, and
in which the metaplectic sign is hidden.

Complexity: O(|W|) arithmetic operations for a word of length |W|.
"""

from __future__ import annotations

import cmath
import math
from typing import List, Sequence, Tuple

Matrix = Tuple[Tuple[float, float], Tuple[float, float]]
Letter = Tuple[str, float]


def mat_mul(m: Matrix, n: Matrix) -> Matrix:
    (a, b), (c, d) = m
    (p, q), (r, s) = n
    return ((a * p + b * r, a * q + b * s), (c * p + d * r, c * q + d * s))


def shear_mat(c: float) -> Matrix:
    return ((1.0, 0.0), (-2.0 * c, 1.0))


def dil_mat(u: float) -> Matrix:
    return ((math.exp(u), 0.0), (0.0, math.exp(-u)))


def fourier_mat() -> Matrix:
    return ((0.0, -1.0), (1.0, 0.0))


def letter_matrix(letter: Letter) -> Matrix:
    kind, param = letter
    if kind == "chirp":
        return shear_mat(param)
    if kind == "dilate":
        return dil_mat(param)
    if kind == "fourier":
        return fourier_mat()
    raise ValueError(f"unknown letter {kind!r}")


def moebius(m: Matrix, z: complex) -> complex:
    (p, q), (r, w) = m
    return (p * z + q) / (r * z + w)


def evaluate_word(word: Sequence[Letter], tau: complex
                  ) -> Tuple[Matrix, complex, complex, List[str]]:
    """Return (accumulated matrix, final tau, accumulated scalar, trace log)."""
    if tau.real <= 0.0:
        raise ValueError("the window must have positive real width")
    matrix: Matrix = ((1.0, 0.0), (0.0, 1.0))
    scalar: complex = 1.0 + 0.0j
    log: List[str] = []
    for letter in word:
        kind, param = letter
        if kind == "chirp":
            tau = tau - 2j * param
        elif kind == "dilate":
            tau = math.exp(-2.0 * param) * tau
        elif kind == "fourier":
            scalar = scalar * tau ** -0.5
            tau = 1.0 / tau
        else:
            raise ValueError(f"unknown letter {kind!r}")
        matrix = mat_mul(letter_matrix(letter), matrix)
        log.append(f"{kind:<8s}({param:+.3f}) -> tau = {tau:.4f}, "
                   f"scalar = {scalar:.4f}, z = {1j / tau:.4f}")
    return matrix, tau, scalar, log


def equivariance_error(word: Sequence[Letter], tau: complex) -> float:
    """How far the Siegel parameter of the output is from the Moebius prediction."""
    matrix, tau_out, _, _ = evaluate_word(word, tau)
    return abs(1j / tau_out - moebius(matrix, 1j / tau))


if __name__ == "__main__":
    tau0 = 1.0 + 0.0j  # the standard Gaussian exp(-pi t^2), Siegel point i
    words: List[List[Letter]] = [
        [("chirp", 0.4), ("dilate", 0.7)],
        [("fourier", 0.0), ("chirp", -1.1), ("fourier", 0.0)],
        [("dilate", 0.3), ("chirp", 0.9), ("dilate", -0.3)],
        [("fourier", 0.0), ("fourier", 0.0)],
        [("fourier", 0.0)] * 4,
    ]
    for word in words:
        matrix, tau_out, scalar, log = evaluate_word(word, tau0)
        name = " . ".join(k if k == "fourier" else f"{k}({p:+.2f})" for k, p in word)
        print(f"\nword: {name}")
        for line in log:
            print("   ", line)
        print(f"    matrix = {matrix}")
        print(f"    final tau = {tau_out:.6f}, accumulated scalar = {scalar:.6f}")
        print(f"    equivariance error = {equivariance_error(word, tau0):.2e}")
    print("\nNote the fourth word, two Fourier transforms: the matrix is -I, which")
    print("acts trivially on the upper half plane, and the width tau indeed returns")
    print("to its initial value.  The window *shape* is therefore blind to the")
    print("operation.  Applied to a Gabor atom displaced from the origin of phase")
    print("space, however, the same operator is the parity map, sending the atom at")
    print("(a, b) to the atom at (-a, -b) -- a genuinely different window.  That gap")
    print("between the trivial matrix and the nontrivial operator is the metaplectic")
    print("anomaly, quantified by the anomaly detector.")

