function FOURIER-STEP(width, a, b, scalar):
    return (1/width, b, -a, scalar * width * exp(-2*pi*i*a*b))

function ANOMALY-REPORT(s, a, b):
    atom   <- (s, a, b, 1)
    twice  <- FOURIER-STEP(FOURIER-STEP(atom))
    fourth <- FOURIER-STEP(FOURIER-STEP(twice))
    parity <- (s, -a, -b, 1)
    d_par  <- sup over grid | twice(t) - parity(t) |        # theorem: 0
    d_self <- sup over grid | twice(t) - atom(t)   |        # theorem: > 0 unless a=b=0
    kappa  <- <twice, atom> / <twice, twice>                # least-squares optimum
    resid  <- sup over grid | kappa*twice(t) - atom(t) |    # theorem: > 0
    d_four <- sup over grid | fourth(t) - atom(t)  |        # theorem: 0
    return (d_par, d_self, kappa, resid, d_four)

function LATTICE-COMPATIBLE(c, tol):
    n <- round(2c)
    if |2c - n| <= tol:
        return (TRUE, certificate = n)              # sigma_c preserves the lattice
    else:
        return (FALSE, certificate = (a=1, b=0, image = 2c))   # explicit escapee

function EXHAUSTIVE-CHECK(c, B, tol):               # independent cross-check
    for a in -B..B, for b in -B..B:
        if |(b + 2ca) - round(b + 2ca)| > tol: return FALSE
    return TRUE
